test('allows integer Count values from 0 through 3 inclusive', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(1), true);
  assert.equal(permit(2), true);
  assert.equal(permit(3), true);
});

test('rejects out-of-range Count values and malformed inputs without coercion', () => {
  for (const invalid of [-1, 4, '1', null, undefined, NaN, Infinity, -Infinity, 1.5]) {
    assert.equal(permit(invalid), false, `expected ${String(invalid)} to be rejected`);
  }
});

